#include <iostream>
#include <algorithm>
using namespace std;

long long computeCost(long long number, int maxLen) {
    static long long p[17];
    if (p[1] == 0) {
        p[1] = 11;
        for (int i = 2; i < 17; ++i) {
            p[i] = p[i - 1] * 10 + 1;
        }
    }
    if (maxLen == 0) return 0;
    long long base = p[maxLen];
    long long quotient = number / base;
    long long remainder = number % base;
    long long cost = quotient * maxLen;
    if (remainder != 0) {
        long long optionA = computeCost(remainder, maxLen - 1);
        long long optionB = maxLen + computeCost(base - remainder, maxLen - 1);
        cost += min(optionA, optionB);
    }
    return cost;
}

int main() {
    ios::sync_with_stdio(false);
    long long n;
    cin >> n;
    cout << computeCost(n, 16) << "\n";
    return 0;
}
